import { useState } from "react";
import React from "react";
import AddTaskModal from "./AddTaskModal";
import EditTaskModal from "./EditTaskModal";
import api from "../services/api";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskListProps{
    tasks: Task[];
    markTaskAsDone: (id: number) => void;
    onTaskAdded: () => void;
    onTaskUpdated: () => void;
    onTaskDeleted: () => void;
}

const TaskList: React.FC<TaskListProps> = ({ tasks, markTaskAsDone, onTaskAdded, onTaskUpdated, onTaskDeleted }) => {
    const [showAddModal, setShowAddModal] = useState(false);
    const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);

    const deleteTask = async (id: number) => {
        const confirmDelete = window.confirm("Are you sure you want to delete this task?");
        if(!confirmDelete) return;

        try{
            await api.delete(`/task/${id}`);
            onTaskDeleted();
        }catch(error) {
            console.error("Error deleting task: ", error);
            alert("There was an error deleting the task");
        }
    };

    return(
        <div>
            <button onClick={() => setShowAddModal(true)}>New Task</button>

            {showAddModal && <AddTaskModal onClose={() => setShowAddModal(false)} onTaskAdded={onTaskAdded} />}

            {taskToEdit && (
                <EditTaskModal
                    task = {taskToEdit}
                    onClose = {() => setTaskToEdit(null)}
                    onTaskUpdated = {onTaskUpdated}
                />
            )}

            <h2>Task List</h2>

            {tasks.length === 0 ? (
                <p>No available tasks!</p>
            ) : (
                <ul>
                    {tasks.map((task) => (
                        <li key={task.id}>

                            <input
                                type = "checkbox"
                                checked = {task.doneFlag}
                                onChange = {() => markTaskAsDone(task.id)}
                            />

                            <strong style = {{ textDecoration: task.doneFlag ? "line-through" : "none" }}>
                                {task.text}
                            </strong>
                            {" - "}
                            {task.priority}

                            <button onClick={() => setTaskToEdit(task)}>Edit</button>
                            <button onClick={() => deleteTask(task.id)}>Delete</button>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default TaskList;
